#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int main(int argc, char *argv[]) {
    int num_threads = 4;
    char *env_threads = getenv("UPC_NUM_THREADS");
    printf("env_threads=%s\n", env_threads ? env_threads : "(null)");
    if (env_threads != NULL) {
        num_threads = atoi(env_threads);
        if (num_threads <= 0) num_threads = 4;
    }
    printf("num_threads=%d\n", num_threads);
    return 0;
}
CEOF
